add('TS0109',
lang('غسول جود مورنينغ منخفض الحموضة من كوسركس','بداية نظيفة، بقوام جل خفيف.',
'سواء في صباحكِ أو نهاية يومكِ، يبدأ هذا الغسول بجل يتحول إلى رغوة لطيفة بالماء. صيغ بحموضة خفيفة ويضم زيت شجرة الشاي وبيتين ساليسيلات. دلّكيه برفق على وجه مبلل ثم اشطفيه؛ تنظيف للشوائب اليومية يليه ترطيب مناسب، مع إزالة المكياج أولًا عند الحاجة.',
['ينظف الشوائب اليومية','قوام جل يُرغّى بالماء','حموضة خفيفة بحسب وصف الشركة'],
'من جل إلى رغوة خفيفة','يُستخدم على وجه ويدين مبللين ثم يُشطف جيدًا.',
'لمن تفضّل غسول جل يوميًا؛ البشرة الحساسة تحتاج اختبار التحمل خاصة مع زيت شجرة الشاي.',
[('بللي الوجه','أزيلي المكياج أولًا وبللي الوجه واليدين.'),('رغّي ودلّكي','رغّي كمية مناسبة ودلّكي برفق بعيدًا عن العينين والفم.'),('اشطفي','اشطفي بماء فاتر ثم أكملي الترطيب.')],
'تجنّبي ملامسة العينين. خففي الاستخدام إذا ظهر جفاف، وتوقفي عند التهيّج أو التحسس من أحد المكونات.',
['زيت شجرة الشاي','بيتين ساليسيلات','حموضة خفيفة'],
[('هل هو للصباح فقط؟','تذكر الشركة استخدامه صباحًا ومساءً بعد إزالة المكياج.'),('هل أتركه على الوجه؟','لا؛ يُشطف بعد التنظيف.')]),
lang('COSRX Low pH Good Morning Gel Cleanser','A fresh start with a light gel cleanse.',
'Morning or evening, this gel cleanser foams with water to remove daily impurities. The mildly acidic formula contains tea tree oil and betaine salicylate. Massage onto wet skin, rinse and moisturise, removing makeup first when needed.',
['Cleanses daily impurities','Gel-to-foam texture','Mildly acidic formula'],
'A light foaming gel','Use with wet hands and face, then rinse thoroughly.',
'For those preferring a daily gel cleanser; sensitive skin should patch test, particularly for tea tree oil.',
[('Wet skin','Remove makeup first; wet hands and face.'),('Lather','Foam a suitable amount and massage away from eyes and mouth.'),('Rinse','Rinse with lukewarm water, then moisturise.')],
'Avoid eye contact. Reduce use if drying and stop if irritation or sensitivity occurs.',
['Tea tree oil','Betaine salicylate','Mildly acidic pH'],
[('Only for mornings?','The brand also recommends evening use after makeup removal.'),('Leave it on?','No. Rinse after cleansing.')]),
[('https://www.cosrx.com/products/low-ph-good-morning-gel-cleanser','COSRX Low pH Good Morning Gel Cleanser')],brief='Adult woman gently cleansing with foam and water; exact white COSRX Low pH Good Morning tube with green/blue band.')

add('TS0110',
lang('ليب بلامبر AHA/BHA وفيتامين C من كوسركس','لمعة مرطّبة مع إحساس الامتلاء المؤقت.',
'للمسة لامعة على الشفاه، يأتي ليب بلامبر بقوام جل كريمي يلين بحرارتها. يضم أحماض AHA وBHA ومشتق فيتامين C، مع مكوّنات تمنح إحساس المنتج المعبّئ. ابدئي بكمية صغيرة؛ قد يصاحبه وخز يختلف بين الأشخاص. اختاريه للعناية والمظهر المؤقت، دون توقع تغيير دائم في حجم الشفاه.',
['يمنح مظهرًا لامعًا للشفاه','يساعد على نعومة سطح الشفاه','قوام جل كريمي سهل التوزيع'],
'جل كريمي بلمعة مائية','يذوب بحرارة الشفاه، وقد يصاحبه وخز لدى بعض المستخدمات.',
'لمن تتحمل منتجات امتلاء الشفاه المؤقت وتريد لمسة لامعة؛ لا يناسب الشفاه المتهيجة.',
[('جرّبي قليلًا','ابدئي بكمية صغيرة على شفاه سليمة.'),('وزّعي بلطف','مرريه على الشفاه الخارجية مع تجنب الجلد المحيط.'),('راقبي الإحساس','أوقفي الاستخدام واغسليه إذا كان الوخز شديدًا أو ظهر تهيّج.')],
'قد يسبب وخزًا؛ لا يعني ذلك أن عليكِ تحمّل الألم. تجنّبي الشفاه المتشققة أو المجروحة والتحسس من مكوّناته.',
['حمض الستريك AHA','بيتين ساليسيلات BHA','مشتق فيتامين C'],
[('هل الوخز وارد؟','نعم بحسب الشركة، لكن الألم الشديد أو التهيج يستدعيان إزالته والتوقف.'),('هل الامتلاء دائم؟','هو منتج تجميلي للمظهر المؤقت، وليس إجراءً لتغيير حجم الشفاه.')]),
lang('COSRX Refresh AHA BHA Vitamin C Lip Plumper','A glossy finish with a temporary plumping feel.',
'This gel-cream lip product melts with warmth into a glossy layer. It combines AHA, BHA and a vitamin C derivative. Start small: tingling can vary between users. Choose it for cosmetic care and a temporary look, not a permanent change in lip size.',
['Glossy lip appearance','Helps smooth the lip surface','Easy-spreading gel-cream texture'],
'A glossy gel cream','Melts on the lips and may cause tingling.',
'For those who tolerate lip-plumping products; avoid irritated lips.',
[('Start small','Try a small amount on intact lips.'),('Spread gently','Apply to outer lips, avoiding surrounding skin.'),('Watch tolerance','Remove and stop if tingling is intense or irritation develops.')],
'Tingling is possible, but pain should not be endured. Avoid cracked, wounded lips and known ingredient allergies.',
['Citric acid AHA','Betaine salicylate BHA','Vitamin C derivative'],
[('Can it tingle?','Yes, according to the brand; remove if painful or irritating.'),('Permanent fullness?','No. This is cosmetic care for a temporary appearance.')]),
[('https://www.cosrx.com/products/lip-plump-refresh-aha-bha-viamin-c-lip-plumper','COSRX Refresh AHA BHA Vitamin C Lip Plumper')],brief='Adult woman applying a tiny amount of glossy balm to natural lips, exact COSRX Lip Plump jar; no enlarged before/after lips or needles.')

add('TS0218',
lang('سيروم جلو بالبروبوليس والنياسيناميد من بيوتي أوف جوسون','قطرات تمنح روتينكِ لمعة هادئة.',
'لإحساس أكثر ترطيبًا ولمسة ندية، وزّعي بضع قطرات من جلو سيروم بعد التنظيف. يجمع البروبوليس والنياسيناميد في قوام ناعم يساعد على تحسين مظهر الملمس والبهتان. ربّتي بلطف على الوجه والرقبة ثم أكملي بالكريم؛ خطوة عناية يومية تندمج بسهولة دون وعود بتغيير فوري أو موحد لكل بشرة.',
['يساعد على ترطيب البشرة','يدعم مظهرًا أكثر إشراقًا','ينعّم مظهر الملمس والمسام'],
'سيروم ناعم بلمسة ندية','بضع قطرات توزّع وتُربّت حتى الامتصاص.',
'للبشرة التي ترغب بترطيب ولمسة إشراق، مع مراعاة التحسس من منتجات النحل.',
[('قطرات قليلة','ضعي 2–3 قطرات في راحة اليد بعد التنظيف.'),('الوجه والرقبة','وزّعي بلطف مع تجنّب العينين.'),('تربيت خفيف','ربّتي حتى الامتصاص ثم أكملي بالمرطب.')],
'اختبريه موضعيًا. راجعي المكونات عند الحساسية من البروبوليس أو منتجات النحل، وتوقفي عند التهيّج.',
['بروبوليس','نياسيناميد','مكوّنات مرطّبة بحسب العبوة'],
[('كم قطرة أستخدم؟','توصي الشركة بقطرتين إلى ثلاث قطرات.'),('هل هو واقي شمس؟','لا؛ أكملي روتين النهار بواقي الشمس.')]),
lang('Beauty of Joseon Glow Serum: Propolis + Niacinamide','A few drops for a soft, dewy finish.',
'Pat a few drops into your routine for hydration and a dewy look. Propolis and niacinamide help refine the appearance of texture and refresh dull-looking skin. Apply gently over face and neck, then finish with moisturiser.',
['Helps hydrate skin','Supports a brighter-looking finish','Refines the look of texture and pores'],
'A cushiony, dewy serum','Pat in a few drops until absorbed.',
'For skin seeking moisture and glow, with attention to bee-product sensitivity.',
[('Dispense','Take 2–3 drops in your palm after cleansing.'),('Apply','Spread gently over face and neck, avoiding eyes.'),('Pat','Tap until absorbed, then moisturise.')],
'Patch test. Check for propolis or bee-product allergies and stop if irritation develops.',
['Propolis','Niacinamide','Moisturising ingredients listed on your pack'],
[('How many drops?','The manufacturer recommends two to three drops.'),('Is it sunscreen?','No. Finish daytime skincare with sunscreen.')]),
[('https://beautyofjoseon.com/products/glow-serum-propolis-niacinamide?country=US&currency=USD&variant=51833681772916','Beauty of Joseon Glow Serum official product page')],research=['Current official INCI/listing differs from older concentration-led marketing; no 60% propolis or 2% niacinamide concentration asserted without exact-pack confirmation.'],brief='Adult woman patting amber serum with fingertips; exact BOJ Glow Serum dropper bottle shown; dropper does not touch skin.')

add('TS0301',
lang('سيروم العين ريفايف بالجنسنغ والريتينال من بيوتي أوف جوسون','عناية مدروسة بتفاصيل محيط العين.',
'امنحي محيط العين خطوة خفيفة مع سيروم ريفايف. يجمع الجنسنغ والريتينال في قوام سريع الامتصاص، ليساعد على الترطيب وتحسين مظهر الخطوط الدقيقة. ابدئي بقليل وراقبي تحمّل بشرتكِ؛ هذه عناية تدريجية للمنطقة الحساسة، لا تحتاج فركًا أو ملامسة خط الرموش.',
['يرطّب محيط العين','يساعد على تحسين مظهر الخطوط الدقيقة','قوام خفيف غير لزج بحسب الشركة'],
'سيروم كريمي خفيف','كمية صغيرة تربّت برفق حول العين، دون ملامستها مباشرة.',
'لمن ترغب بعناية لمظهر الخطوط والجفاف حول العين وتتحمل الريتينويدات.',
[('ابدئي بقليل','على بشرة نظيفة، خذي كمية صغيرة وابدئي تدريجيًا.'),('حول العين برفق','ربّتي حول محيط العين بعيدًا عن العين نفسها وخط الرموش.'),('أكملي الحماية','أكملي بالمرطب عند الحاجة، واستخدمي واقي الشمس نهارًا.')],
'يحتوي ريتينال؛ تجنّبيه أثناء الحمل والرضاعة وفق الشركة. لا تجمعيه مع AHA/BHA/PHA في الروتين نفسه، وتوقفي عند التهيّج.',
['مستخلص الجنسنغ','ريتينال ضمن نظام ليبوسومات','قوام مرطب خفيف'],
[('هل هو ريتينول؟','المكوّن المذكور هو ريتينال، وهو مختلف عن الريتينول.'),('هل أستخدمه مع الأحماض؟','توصي الشركة بعدم جمعه مع AHA/BHA/PHA لتقليل التهيّج.')]),
lang('Beauty of Joseon Revive Eye Serum: Ginseng + Retinal','Thoughtful care for the eye contour.',
'Ginseng and retinal meet in a quick-absorbing eye serum to hydrate and soften the appearance of fine lines. Start with a little and watch tolerance; the delicate eye area needs gentle patting, not rubbing or application into the lash line.',
['Hydrates the eye contour','Softens the appearance of fine lines','Light, non-sticky serum feel'],
'A lightweight creamy serum','Pat a small amount around the contour, keeping it out of the eyes.',
'For those seeking care for visible fine lines or dryness and who tolerate retinoids.',
[('Start small','Take a small amount on clean skin and introduce gradually.'),('Pat gently','Apply around the eye contour, away from eyes and lash line.'),('Complete','Moisturise if needed and use daytime sunscreen.')],
'Contains retinal. The brand advises avoiding pregnancy and breastfeeding. Do not combine with AHA/BHA/PHA; stop if irritated.',
['Ginseng extract','Retinal in a liposome delivery system','Light moisturising texture'],
[('Is this retinol?','No. The named ingredient is retinal, a different retinoid.'),('Use with acids?','The manufacturer advises against combining with AHA/BHA/PHA.')]),
[('https://beautyofjoseon.com/products/revive-eye-serum-ginseng-retinal?variant=41689275367589','Beauty of Joseon Revive Eye Serum official product page')],research=['No concentration asserted; a liposome-complex percentage must never be presented as the percentage of pure retinal.'],brief='Adult woman gently patting tiny amount on orbital bone; exact pale BOJ Ginseng+Retinal tube; keep cream away from lash line and inner eye.')

expected=set(inputs)
assert len(items)==18 and {x['id'] for x in items}==expected
for p in items:
 for loc in ('ar','en'):
  x=p[loc]
  assert len(x['benefits'])==3 and len(x['steps'])==3 and len(x['faq'])==2
  assert all(isinstance(x[k],str) and x[k].strip() for k in ('name','tagline','description','textureTitle','textureText','fitText','notes'))
 assert p['sources'] and p['usageBrief']
(BASE/'content-1.json').write_text(json.dumps(items,ensure_ascii=False,indent=2)+'\n')
print('Wrote',len(items),'profiles to',BASE/'content-1.json')
print('Status counts:',{s:sum(p['sourceStatus']==s for p in items) for s in ('exact','family','limited')})
